def count_paths(Y, X, x_init, map_data):
    MOD = 1000003
    dp = [[0] * X for _ in range(Y)]
    dp[0][x_init] = 1

    def move_south(x):
        return max(0, min(X-1, x))

    def move_east(x):
        return min(X-1, x+1)

    def move_west(x):
        return max(0, x-1)

    for y in range(1, Y):
        for x in range(X):
            if map_data[y-1][x] == '@':
                continue
            if map_data[y-1][x] == 'v':
                dp[y][move_south(x)] += dp[y-1][x]
                dp[y][move_south(x)] %= MOD
            elif map_data[y-1][x] == '>':
                dp[y][move_east(x)] += dp[y-1][x]
                dp[y][move_east(x)] %= MOD
            elif map_data[y-1][x] == '<':
                dp[y][move_west(x)] += dp[y-1][x]
                dp[y][move_west(x)] %= MOD
            else:
                dp[y][x] += dp[y-1][x]
                dp[y][x] %= MOD

    return dp[-1].count(1)

