def count_paths(Y, X, x_init, grid):
    MOD = 1000003
    directions = [(-1, 0), (0, -1), (0, 1)]  # North, West, East
    dp = [[[-1] * 2 for _ in range(X)] for _ in range(Y)]

    def is_valid(x, y):
        return 0 <= x < Y and 0 <= y < X

    def dfs(x, y, sail_up):
        if not is_valid(x, y) or grid[x][y] == '#':
            return 0
        if grid[x][y] == '@':
            return 1

        if dp[x][y][sail_up] != -1:
            return dp[x][y][sail_up]

        total_paths = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (dx == -1 and grid[nx][ny] == 'a') or (dy > 0 and grid[nx][ny] == '>') or (dy < 0 and grid[nx][ny] == '<'):
                total_paths = (total_paths + dfs(nx, ny, True)) % MOD
            elif dx == -1:
                total_paths = (total_paths + dfs(nx, ny, False)) % MOD

        dp[x][y][sail_up] = total_paths
        return total_paths

    return dfs(Y - 1, x_init, False)

