def find_paths(Y, X, x_init, map_data):
    MOD = 1000003
    directions = [(-1, 0), (0, 1), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < Y and 0 <= y < X

    def can_move_to(x, y):
        return map_data[x][y] != '#'

    def dfs(x, y, east, west):
        if x == 0 and can_move_to(0, y):
            return 1

        result = 0
        if can_move_to(x, y):
            result += dfs(x + 1, y, east, west)

        if map_data[x][y] == '>':
            if can_move_to(x, min(y + east + 1, X - 1)):
                result += dfs(x, min(y + east + 1, X - 1), east + 1, west)
        elif map_data[x][y] == '<':
            if can_move_to(x, max(y - west - 1, 0)):
                result += dfs(x, max(y - west - 1, 0), east, west + 1)
        elif map_data[x][y] == '~':
            result += dfs(x, y, east, west)

        return result % MOD

    return dfs(0, x_init, 0, 0)

