from collections import deque

def count_paths(Y, X, x_init, map_data):
    MOD = 1000003
    moves = {'>': (0, 1), '<': (0, -1), '~': None}
    directions = [(-1, 0), (0, 1), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < Y and 0 <= y < X and map_data[x][y] != '#'

    def dfs(x, y, steps, current_path):
        nonlocal count
        if (x, y) == (0, x_init):
            count = (count + 1) % MOD
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                dfs(nx, ny, steps, current_path + [(nx, ny)])

    count = 0
    stack = [(Y - 1, x_init)]
    visited = set()
    while stack:
        x, y = stack.pop()
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if map_data[x][y] == '@':
            dfs(x, y, 0, [(x, y)])
        else:
            dx, dy = moves[map_data[x][y]]
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                stack.append((nx, ny))

    return count if count > 0 else "begin repairs"

